      "expected": "Spec lists two otter_CH330 USB-UART bridges in the Connections sheet.",
      "evidence": [
        {"source": "spec", "quote": "USB-UART bridges (programming/debug) | Connections | otter_CH330 ×2"},
        {"source": "netlist", "quote": "No component with value 'CH330' appears in the components list."}
      ],
      "impact": "USB programming/debug interface does not work.",
      "confidence": 1.0
    },
    {
      "category": "short_to_supply",
      "components": ["U15"],
      "pins": ["U15.1"],
      "nets": ["+3.3V", "GND"],
      "observed": "U15 pin1 (A0) is connected to +3.3V. Other address pins A1-A5 (pins 2,3,4,5,24) are on GND.",
      "expected": "Spec says PCA9685PW I2C addr 0x40. With A0=1, the address becomes 0x41.",
      "evidence": [
        {"source": "netlist", "quote": "(node (ref \"U15\") (pin \"1\") (pinfunction \"A0\") (pintype \"input\")) on net +3.3V"},
        {"source": "spec", "quote": "PWM/servo driver | FCCPeripherals | NXP PCA9685PW (I2C 16-ch PWM), I2C addr 0x40"}
      ],
      "impact": "Software trying to communicate at 0x40 will fail; PWM/servo driver not accessible.",
      "confidence": 0.95
